using System.Data;using Servicio.RetazoMarket.DataManagment.Interfaces;using Servicio.RetazoMarket.DataManagment.Mappers;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.DataManagment.Services;
public class DescuentoAdministracionDataService:IDescuentoAdministracionDataService {private readonly IUnitOfWork _uow;public DescuentoAdministracionDataService(IUnitOfWork uow)=>_uow=uow;public async Task<DescuentoDataModel> CrearAsync(DescuentoDataModel model,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var entity=DescuentoDataMapper.ToEntity(model);await _uow.DescuentoRepository.AgregarAsync(entity,ct);await _uow.SaveChangesAsync(ct);await SincronizarIndicadorAsync(model.id_producto,ct);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);return DescuentoDataMapper.ToDataModel(entity);}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}public async Task<DescuentoDataModel?> ActualizarAsync(DescuentoDataModel model,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var entity=await _uow.DescuentoRepository.ObtenerParaActualizarAsync(model.id_descuento,ct);if(entity is null){await _uow.RollbackTransactionAsync(ct);return null;}var productoAnterior=entity.id_producto;DescuentoDataMapper.ApplyToEntity(model,entity);_uow.DescuentoRepository.Actualizar(entity);await _uow.SaveChangesAsync(ct);await SincronizarIndicadorAsync(productoAnterior,ct);if(model.id_producto!=productoAnterior)await SincronizarIndicadorAsync(model.id_producto,ct);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);return DescuentoDataMapper.ToDataModel(entity);}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}public async Task<bool> InactivarAsync(int id,CancellationToken ct=default){await _uow.BeginTransactionAsync(IsolationLevel.Serializable,ct);try{var entity=await _uow.DescuentoRepository.ObtenerParaActualizarAsync(id,ct);if(entity is null){await _uow.RollbackTransactionAsync(ct);return false;}entity.estado="INA";_uow.DescuentoRepository.Actualizar(entity);await _uow.SaveChangesAsync(ct);await SincronizarIndicadorAsync(entity.id_producto,ct);await _uow.SaveChangesAsync(ct);await _uow.CommitTransactionAsync(ct);return true;}catch{try{await _uow.RollbackTransactionAsync(CancellationToken.None);}finally{_uow.DescartarCambios();}throw;}}private async Task SincronizarIndicadorAsync(int productoId,CancellationToken ct){var producto=await _uow.ProductoRepository.ObtenerParaActualizarAsync(productoId,ct)??throw new InvalidOperationException("El producto no existe.");var reglas=await _uow.DescuentoRepository.ObtenerPorProductoAsync(productoId,ct);producto.tiene_descuentos=reglas.Any(x=>x.estado=="ACT")?"S":"N";_uow.ProductoRepository.Actualizar(producto);}}
